const dateText=t=>new Date(t).toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).replace('T',' ');
const timeText=t=>dateText(t).slice(5,16);
const relative=t=>{let m=Math.max(0,Math.floor((now-t)/60000));return m<60?`${m} 分钟前`:m<1440?`${Math.floor(m/60)} 小时前`:`${Math.floor(m/1440)} 天前`};
const sources=[{name:'ZCode',cap:'Token 完整',grade:'complete',status:'已发现',last:'14:28',records:'逐请求用量'}, {name:'DSH',cap:'Token 完整',grade:'complete',status:'已发现',last:'14:28',records:'会话用量 · 重复回放已过滤'}, {name:'WorkBuddy',cap:'Token 完整',grade:'complete',status:'已发现',last:'14:28',records:'缓存与非缓存输入分开'}, {name:'CatPaw',cap:'仅活动',grade:'activity',status:'已发现',last:'14:28',records:'消息活动 · 无 Token'}, {name:'Trae',cap:'仅活动 / 未知',grade:'activity',status:'已发现',last:'14:28',records:'记忆活动；另有不可读存储'}];
const projects=[
 {key:'p_fox',name:'狐写',original:'狐写-v1源代码',kind:'工作目录',mark:'狐',path:'… / 狐写-v1源代码 / ForWrite',scale:8.4},
 {key:'p_ledger',name:'AI 用量账本',original:'usage-ledger',kind:'工作目录',mark:'账',path:'… / usage-ledger',scale:5.5},
 {key:'p_site',name:'个人网站',original:'portfolio',kind:'工作目录',mark:'P',path:'… / portfolio',scale:3.5},
 {key:'p_auto',name:'公众号系统',original:'公众号系统',kind:'工作目录',mark:'公',path:'… / 公众号系统',scale:2.4},
 {key:'p_notes',name:'知识整理',original:'knowledge',kind:'工作目录',mark:'知',path:'… / knowledge',scale:1.4},
 {key:'p_lab',name:'模型实验',original:'model-lab',kind:'工作目录',mark:'M',path:'… / model-lab',scale:.65},
 {key:'p_unassigned',name:'待整理记录',original:'Unassigned',kind:'未识别目录',mark:'?',path:'未发现工作目录',scale:.3}
];
const sessionNames=['完成编辑器重构','联调与验收','修复边界状态','整理桌面布局','补全项目文档','记录工作进展'];
const models=['glm-4.7','deepseek-v3.2','claude-sonnet-4.5'];
const sessions=[];const records=[];
projects.forEach((p,pi)=>{
 for(let si=0;si<6;si++){
  const source=sources[si%5].name;const sid=`s_${pi}_${si}`;const activity=['CatPaw','Trae'].includes(source);
  const model=activity?null:models[si%3];
  const base=now-(pi*29+si*83+12)*60000-(si===2?7:si===5?21:0)*86400000;
  sessions.push({id:sid,project:p.key,originalProject:p.key,title:sessionNames[si],source,model,agent:activity?null:'默认助手'});
  for(let ei=0;ei<16;ei++){
   const input=activity?null:Math.round(p.scale*(11000+ei*770+si*880));const output=activity?null:Math.round(p.scale*(900+ei*160));const cache=activity?null:Math.round(p.scale*(23000+ei*1450));
   const currency=source==='ZCode'?'CNY':'USD';const priced=!activity&&!(p.key==='p_unassigned'||(si===5&&ei%7===0));
   const cost=priced?Math.round((input*(currency==='CNY'?.000004:.0000015)+output*(currency==='CNY'?.000014:.000009)+cache*(currency==='CNY'?.0000005:.00000015))*10000)/10000:null;
   records.push({id:`e_${pi}_${si}_${ei}`,project:p.key,originalProject:p.key,session:sid,source,model,input,output,cache,total:activity?null:input+output,currency,cost,ts:base-ei*19*60000,activity,replay:false,unknown:false});
  }
 }
});
records.filter(e=>e.source==='DSH'&&!e.activity).slice(0,14).forEach((e,i)=>records.push({...e,id:`replay_${i}`,replay:true}));
for(let i=0;i<3;i++)records.push({id:`unknown_${i}`,project:'p_unassigned',session:null,source:'Trae',model:null,input:null,output:null,cache:null,total:null,cost:null,ts:now-(i+1)*3600000,activity:false,replay:false,unknown:true});
const params=new URLSearchParams(location.search);
const state={view:params.get('view')||'overview',scenario:params.get('scenario')||'default',range:'30',project:'all',client:'all',model:'all',sort:'tokens',chosenProject:'p_fox',chosenSession:'s_0_0',chosenEvent:null,eventPage:0,audit:'effective',onboarding:params.get('step')||'welcome',attributionTab:params.get('tab')||'alias',scan:'idle',scanResult:'success',overlay:null,origin:'overview',settingTab:params.get('setting')||'common',disclosures:{},startup:false};
function effective(){
 const days=state.range==='all'?Infinity:Number(state.range);const cutoff=state.range==='1'?Date.parse('2026-10-02T00:00:00+08:00'):now-days*86400000;
 return records.filter(e=>!e.replay&&e.ts>=cutoff&&(state.project==='all'||e.project===state.project)&&(state.client==='all'||e.source===state.client)&&(state.model==='all'||e.model===state.model));
}
function aggregate(events){
 const token=events.filter(e=>e.total!=null),activity=events.filter(e=>e.activity),unknown=events.filter(e=>e.unknown);
 const costs={CNY:null,USD:null};for(const e of token){if(e.cost!=null)costs[e.currency]=(costs[e.currency]??0)+e.cost}
 return {input:token.reduce((n,e)=>n+e.input,0),output:token.reduce((n,e)=>n+e.output,0),cache:token.reduce((n,e)=>n+e.cache,0),total:token.reduce((n,e)=>n+e.total,0),hasTokens:token.length>0,costs,activity:activity.length,unknown:unknown.length,events:events.length,sessions:new Set(events.map(e=>e.session).filter(Boolean)).size,projectCount:new Set(events.map(e=>e.project).filter(p=>p!=='p_unassigned')).size,last:Math.max(...events.map(e=>e.ts),0),unpriced:token.filter(e=>e.cost==null).length,pricedTokens:token.filter(e=>e.cost!=null).reduce((n,e)=>n+e.total,0),priced:token.filter(e=>e.cost!=null).length};
}
function costHTML(a){const c=['CNY','USD'].filter(c=>a.costs[c]!=null).map(c=>money(a.costs[c],c));return c.length?c.join(' <span class="currency-separator">／</span> '):a.hasTokens?'暂无价格':'暂不能估算'}
function projectData(){
 let arr=projects.map(p=>({...p,summary:aggregate(effective().filter(e=>e.project===p.key))})).filter(p=>p.summary.events);
 arr.sort((a,b)=>state.sort==='last'?b.summary.last-a.summary.last:state.sort.startsWith('cost')?(b.summary.costs[state.sort.slice(5)]??-1)-(a.summary.costs[state.sort.slice(5)]??-1):b.summary.total-a.summary.total);return arr;
}
